using Compose.Net;using DesignSystem;using SharpExtensions;// ReSharper disable ArrangeNamespaceBodynamespace UnityCompose.Samples.Behaviors.Content{    internal partial class ButtonSample : ComposeUI    {        [SerializeField] private Texture2D texture = null!;        [SerializeField] private Material material = null!;        [Composable]        protected override void Content() => Layout();        [Composable]        protected override void Preview() => Layout();        [Composable]        private void Layout()        {            Column(                verticalArrangement: Arrangement.Center,                horizontalAlignment: Alignment.CenterHorizontally,                modifier: Modifier                    .FillMaxSize(),                content: () =>                {                    var interactionSource = Remember(MutableInteractionSource);                    var hovered = interactionSource.CollectIsHoveredAsState().Value;                    var shadowProgress = AnimateFloatAsState(hovered.ToInt()).Value;                    var pressed = interactionSource.CollectIsPressedAsState().Value;                    Box(                        alignment: Alignment.Center,                        modifier: Modifier                            .Height(200.Dp())                            .Width(600.Dp())                            .Background(                                Brush.LinearGradient(                                    ImmutableStableListOf(                                        Color.lightGreen.ToSystemColor(),                                        Color.dodgerBlue.ToSystemColor()                                    )                                ),                                RoundedCornerShape(16.Dp())                            )                            .Border(                                8.Dp(),                                Brush.LinearGradient(                                    ImmutableStableListOf(                                        Color.red.ToSystemColor(),                                        Color.yellow.ToSystemColor()                                    )                                ),                                RoundedCornerShape(4.Dp())                            )                            .Padding(16.Dp())                            .Clickable(interactionSource)                            .Hoverable(interactionSource)                            .Clip(RoundedCornerShape(AnimateFloatAsState(hovered ? 48 : 16).Value.Dp()))                            .Scale(AnimateFloatAsState(1 + 0.05f * shadowProgress).Value)                            .DropShadow(                                shape: RoundedCornerShape(16.Dp()),                                shadow: Shadow(                                    spread: 20.Dp(),                                    color: Color.LerpUnclamped(new Color(), Color.black, shadowProgress)                                        .ToSystemColor(),                                    radius: 32.Dp() * shadowProgress                                )                            )                            .InnerShadow(                                shape: RoundedCornerShape(16.Dp()),                                shadow: Shadow(                                    spread: 8.Dp(),                                    color: Color.LerpUnclamped(new Color(), Color.white.With(a: 0.5f), 1)                                        .ToSystemColor(),                                    radius: 12.Dp()                                )                            )                            .Draw(it =>                            {                                var size = new Size(200, 200) * (1 + 0.2f * shadowProgress);                                it.DrawImage(                                    image: ImageBitmap.ImageResource(texture),                                    alpha: 0.5f,                                    topLeft: it.Size.ToOffset() / 2 - size.ToOffset() / 2,                                    size: size                                );                            })                            .Draw(it =>                            {                                it.DrawRect(                                    brush: Brush.LinearGradient(                                        ImmutableStableListOf(                                            Color.lightGreen.ToSystemColor(),                                            Color.dodgerBlue.ToSystemColor()                                        )                                    ),                                    alpha: 0.5f                                );                            })                            .ClickIndication(interactionSource),                        content: () =>                        {                            Text(                                text: pressed ? "Clicked" : "Click me",                                color: Color.white.ToSystemColor(),                                fontSize: 80.Sp()                            );                        }                    );                }            );        }    }    internal static partial class ModifierExtensions    {        public static IModifier ClickIndication(            this IModifier modifier,            IMutableInteractionSource? interactionSource = null,            bool enabled = true        )        {            if (!enabled)                return modifier;            return modifier.Composed(interactionSource, () =>            {                interactionSource ??= Remember(MutableInteractionSource);                interactionSource = interactionSource.NotNull();                var hovered = interactionSource.CollectIsHoveredAsState().Value;                var pressed = interactionSource.CollectIsPressedAsState().Value;                var hoveredScale = AnimateFloatAsState(hovered ? 1.05f : 0.8f).Value;                var hoveredOpacity = 0.2f * AnimateFloatAsState((hovered && !pressed).ToInt()).Value;                var pressAnimationSpec = Tween(300);                var pressScale = AnimateFloatAsState(pressed.ToInt(), pressAnimationSpec).Value;                var pressOpacity = 0.8f * AnimateFloatAsState(pressed.ToInt(), pressAnimationSpec).Value;                return Modifier                    .Hoverable(interactionSource)                    .Clickable(interactionSource)                    .DrawOnTop(it =>                    {                        var size = it.Size * hoveredScale;                        var topLeft = (it.Size - size) / 2;                        it.DrawRoundRect(                            color: Color.white.ToSystemColor(),                            topLeft: topLeft.ToOffset(),                            size: it.Size * hoveredScale,                            cornerRadius: 32,                            alpha: hoveredOpacity                        );                        var maxSize = Mathf.Max(it.Size.Width, it.Size.Height);                        it.DrawCircle(                            color: Color.black.ToSystemColor(),                            center: it.Size.ToOffset() / 2,                            radius: maxSize * pressScale,                            alpha: pressOpacity                        );                    });            });        }    }}